globalsCss:
@import "tailwindcss";

@theme {
  /* ── Brand Colors ─────────────────────────────── */
  --color-bg: #FAF8F3;
  --color-surface: #F2EBE0;
  --color-surface-alt: #E8DDD0;
  --color-ink: #1A1210;
  --color-ink-soft: #5C5248;
  --color-primary: #C13A0F;
  --color-primary-dark: #8B2200;
  --color-secondary: #2E6B4A;
  --color-accent: #F5A623;
  --color-line: #DED5C7;
  --color-white: #FFFFFF;

  /* ── Typography ───────────────────────────────── */
  --font-display: var(--font-fraunces), Georgia, "Times New Roman", serif;
  --font-body: var(--font-inter), system-ui, -apple-system, sans-serif;

  /* ── Border Radius ────────────────────────────── */
  --radius-xs: 0.25rem;
  --radius-sm: 0.375rem;
  --radius-md: 0.75rem;
  --radius-lg: 1.25rem;
  --radius-xl: 2rem;
  --radius-2xl: 3rem;
  --radius-full: 9999px;

  /* ── Shadows ──────────────────────────────────── */
  --shadow-card: 0 4px 24px -4px rgba(26,18,16,0.10), 0 1px 6px -1px rgba(26,18,16,0.06);
  --shadow-lifted: 0 16px 48px -8px rgba(193,58,15,0.20), 0 4px 16px -4px rgba(26,18,16,0.12);
  --shadow-glass: 0 8px 32px 0 rgba(26,18,16,0.08);
  --shadow-focus: 0 0 0 3px rgba(193,58,15,0.35);

  /* ── Layout Tokens ────────────────────────────── */
  --section-y: 6rem;
  --container-max: 1280px;
  --gutter: 1.5rem;
  --bento-gap: 1rem;
}

@layer base {
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    font-size: 16px;
  }

  body {
    background-color: var(--color-bg);
    color: var(--color-ink);
    font-family: var(--font-body);
    font-size: 1rem;
    line-height: 1.65;
    min-height: 100dvh;
    overflow-x: hidden;
  }

  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-display);
    font-weight: 900;
    line-height: 1.05;
    letter-spacing: -0.025em;
    color: var(--color-ink);
    text-wrap: balance;
  }

  p {
    color: var(--color-ink-soft);
    max-width: 68ch;
    text-wrap: pretty;
  }

  a {
    color: var(--color-primary);
    text-underline-offset: 0.2em;
    text-decoration-thickness: 1px;
    transition: color 0.2s ease;
  }

  a:hover {
    color: var(--color-primary-dark);
  }

  img, video {
    max-width: 100%;
    display: block;
  }

  ul, ol {
    list-style: none;
  }

  button {
    cursor: pointer;
    border: none;
    background: none;
    font-family: inherit;
  }

  ::selection {
    background-color: var(--color-primary);
    color: #FFFFFF;
  }

  :focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: 3px;
    border-radius: var(--radius-sm);
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }
}

@layer utilities {
  /* ── Glassmorphism ────────────────────────────── */
  .glass {
    background: rgba(250, 248, 243, 0.75);
    backdrop-filter: blur(20px) saturate(1.5);
    -webkit-backdrop-filter: blur(20px) saturate(1.5);
    border: 1px solid rgba(222, 213, 199, 0.55);
  }

  .glass-dark {
    background: rgba(26, 18, 16, 0.80);
    backdrop-filter: blur(20px) saturate(1.4);
    -webkit-backdrop-filter: blur(20px) saturate(1.4);
    border: 1px solid rgba(255, 255, 255, 0.07);
    color: #FFFFFF;
  }

  .glass-primary {
    background: rgba(193, 58, 15, 0.10);
    backdrop-filter: blur(16px) saturate(1.3);
    -webkit-backdrop-filter: blur(16px) saturate(1.3);
    border: 1px solid rgba(193, 58, 15, 0.22);
  }

  /* ── Typography helpers ───────────────────────── */
  .text-balance {
    text-wrap: balance;
  }

  .text-pretty {
    text-wrap: pretty;
  }

  .font-display {
    font-family: var(--font-display);
  }

  .font-body {
    font-family: var(--font-body);
  }

  /* ── Layout helpers ───────────────────────────── */
  .section-padding {
    padding-top: var(--section-y);
    padding-bottom: var(--section-y);
    padding-left: var(--gutter);
    padding-right: var(--gutter);
  }

  .container-max {
    max-width: var(--container-max);
    margin-left: auto;
    margin-right: auto;
    padding-left: var(--gutter);
    padding-right: var(--gutter);
  }

  /* ── Bento grid ───────────────────────────────── */
  .bento-grid {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    gap: var(--bento-gap);
  }

  .bento-grid-4 {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--bento-gap);
  }

  @media (max-width: 768px) {
    .bento-grid,
    .bento-grid-4 {
      grid-template-columns: 1fr;
    }
  }

  /* ── Brand gradients ──────────────────────────── */
  .gradient-brand {
    background: linear-gradient(
      135deg,
      var(--color-primary-dark) 0%,
      var(--color-primary) 50%,
      var(--color-accent) 100%
    );
  }

  .gradient-warm {
    background: linear-gradient(
      160deg,
      var(--color-bg) 0%,
      var(--color-surface) 100%
    );
  }

  .gradient-hero-overlay {
    background: linear-gradient(
      to right,
      rgba(26, 18, 16, 0.72) 0%,
      rgba(26, 18, 16, 0.30) 60%,
      transparent 100%
    );
  }

  /* ── Card base ────────────────────────────────── */
  .card {
    background-color: var(--color-surface);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-card);
    overflow: hidden;
    transition: box-shadow 0.3s ease, transform 0.3s ease;
  }

  .card:hover {
    box-shadow: var(--shadow-lifted);
    transform: translateY(-6px);
  }

  /* ── Noise texture overlay ────────────────────── */
  .noise-overlay {
    position: relative;
    isolation: isolate;
  }

  .noise-overlay::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.035'/%3E%3C/svg%3E");
    pointer-events: none;
    border-radius: inherit;
    z-index: 1;
  }

  /* ── Pill badge ───────────────────────────────── */
  .badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.2em 0.65em;
    border-radius: var(--radius-full);
    font-size: 0.75rem;
    font-weight: 600;
    font-family: var(--font-body);
    line-height: 1.4;
    letter-spacing: 0.02em;
    text-transform: uppercase;
  }

  .badge-veg {
    background-color: rgba(46, 107, 74, 0.12);
    color: var(--color-secondary);
    border: 1px solid rgba(46, 107, 74, 0.25);
  }

  .badge-accent {
    background-color: var(--color-accent);
    color: var(--color-ink);
  }

  .badge-primary {
    background-color: var(--color-primary);
    color: #FFFFFF;
  }

  /* ── Scroll snap (gallery) ────────────────────── */
  .snap-x-mandatory {
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
  }

  .snap-start {
    scroll-snap-align: start;
  }
}
